let lic={i:0,correct:0,locked:false};function renderLicense(){if(lic.i>=license.length){el('v4LicenseQuestion').textContent=lic.correct===6?'🏆 Alle Sicherheitsfragen richtig!':'Du hast den Sicherheitstest abgeschlossen.';el('v4LicenseChoices').innerHTML='';el('v4LicenseCount').textContent='Auswertung';status('v4LicenseFeedback',`${lic.correct}/6 richtig. ${lic.correct===6?'Digitale Lernkontrolle bestanden. Ein praktischer Brennerführerschein muss im Unterricht durch die Lehrkraft bestätigt werden.':'Wiederhole die Regeln und versuche es erneut.'}`,lic.correct===6);el('v4LicenseNext').disabled=true;if(lic.correct===6)mark('license');return}let [q,opts]=license[lic.i];el('v4LicenseCount').textContent=`Frage ${lic.i+1} von 6`;el('v4LicenseQuestion').textContent=q;el('v4LicenseChoices').innerHTML=opts.map((t,j)=>`<button data-lic="${j}">${clean(t)}</button>`).join('');lic.locked=false;el('v4LicenseNext').disabled=true;status('v4LicenseFeedback','Welche Antwort ist sicher?');all('[data-lic]').forEach(b=>b.addEventListener('click',()=>{if(lic.locked)return;lic.locked=true;let good=+b.dataset.lic===license[lic.i][2];if(good)lic.correct++;b.classList.add(good?'correct':'wrong');all('[data-lic]').forEach(x=>x.disabled=true);status('v4LicenseFeedback',(good?'Richtig. ':'Nicht ganz. ')+license[lic.i][3],good);el('v4LicenseNext').disabled=false}))}
