const topicNames={matter:'Stoffe und Körper',dissolve:'Löslichkeit',boil:'Siedetemperatur',safety:'Sicherheit',devices:'Laborgeräte',burner:'Gasbrenner'};
window.LernCockpitBankChem=BANK; function stats(t){return data.stats[t]||{right:0,wrong:0}}
function addStat(topic,correct,itemId){const s=stats(topic);s[correct?'right':'wrong']++;data.stats[topic]=s;save(); window.LernCockpit?.record({id:'chem-bank-'+BANK.findIndex(x=>x[1]===itemId),topic:({'dissolve':'solubility','boil':'heating'})[topic]||topic,correct,assisted:false,mode:'trainer',skill:'wissen'})}
function renderStats(){el('v4TopicStats').innerHTML=Object.keys(topicNames).map(k=>{const s=stats(k),n=s.right+s.wrong,rate=n?Math.round(s.right/n*100):0;return `<div class="v4stat"><h4>${topicNames[k]}</h4><small>${n?n+' Fragen · '+rate+' % richtig':'Noch nicht geübt'}</small><div class="v4meter" title="${rate}% richtig"><i style="width:${rate}%"></i></div></div>`}).join('')}
let trainer={items:[],i:0,correct:0,answered:false};
function chooseTraining(){const focus=el('v4TrainerFocus').value;let pool=[...BANK];if(focus!=='auto')pool=pool.filter(x=>x[0]===focus);else {pool.sort((a,b)=>{const A=stats(a[0]),B=stats(b[0]);const urgency=s=>(s.wrong+1)/(s.right+s.wrong+1);return urgency(B)-urgency(A)})}let selected=[];if(focus==='auto'){let weakTopics=Object.keys(topicNames).sort((a,b)=>{let sa=stats(a),sb=stats(b);return (sb.wrong+1)/(sb.right+sb.wrong+1)-(sa.wrong+1)/(sa.right+sa.wrong+1)});for(let k of weakTopics)selected.push(...pool.filter(q=>q[0]===k).slice(0,1));selected=selected.slice(0,5)}else selected=pool.slice(0,5);return selected}
function renderTraining(){const board=el('v4TrainerBoard');if(trainer.i>=trainer.items.length){board.innerHTML=`<h3>Übung abgeschlossen</h3><p>${trainer.correct} von ${trainer.items.length} richtig. Schau dir die Rückmeldung an und wiederhole gezielt schwierige Themen.</p><button class="v4btn" id="v4TrainerAgain">Noch einmal üben</button>`;el('v4TrainerAgain').addEventListener('click',startTraining);renderStats();mark('adaptive');return}const q=trainer.items[trainer.i];trainer.answered=false;board.innerHTML=`<div class="v4kicker">Frage ${trainer.i+1} von ${trainer.items.length} · ${topicNames[q[0]]}</div><h3>${clean(q[1])}</h3><div class="v4choices" id="v4TrainingChoices">${q[2].map((v,j)=>`<button data-v4train="${j}">${clean(v)}</button>`).join('')}</div><div id="v4TrainingFeedback" class="v4outcome" role="status">Wähle eine Antwort.</div><button class="v4btn" id="v4TrainNext" disabled>Weiter →</button>`;all('[data-v4train]').forEach(b=>b.addEventListener('click',()=>{if(trainer.answered)return;trainer.answered=true;const right=+b.dataset.v4train===q[3];if(right)trainer.correct++;addStat(q[0],right,q[1]);b.classList.add(right?'correct':'wrong');all('[data-v4train]').forEach(x=>x.disabled=true);status('v4TrainingFeedback',(right?'Richtig! ':'Noch nicht. ')+q[4],right);el('v4TrainNext').disabled=false;renderStats()}));el('v4TrainNext').addEventListener('click',()=>{trainer.i++;renderTraining()})}
function startTraining(){trainer={items:chooseTraining(),i:0,correct:0,answered:false};renderTraining()}el('v4TrainerStart').addEventListener('click',startTraining);renderStats();
// -- 12 question mock exam, some written explanations are self-assessed (not auto-graded).
const written=[
['Erläutere den Unterschied zwischen Körper und Stoff und nenne ein Beispiel.','Ein Körper ist ein konkreter Gegenstand (z. B. Fenster), ein Stoff das Material (z. B. Glas).'],
['Nenne zwei Bedingungen, die du bei einem fairen Löslichkeitsvergleich gleich halten solltest.','Gleiche Wassermenge, gleiche Temperatur, gleiche Menge bzw. Masse pro Schritt, gleiche Rührzeit (mindestens zwei).'],
['Erkläre den Unterschied zwischen Verdunsten und Sieden.','Verdunsten findet an der Oberfläche schon unter dem Siedepunkt statt; beim Sieden entstehen auch im Inneren Dampfblasen.'],
['Warum ist das Filtrieren einer Salzlösung nicht geeignet, um das Salz abzutrennen?','Die gelösten Ionen sind zu klein und passieren das gewöhnliche Filterpapier mit dem Wasser.']
];
const mockBank=[{q:'Welche zwei Begriffe gehören zusammen?',o:['Fensterscheibe – Glas','Gold – Fenster','Luft – Tisch'],a:0,why:'Fensterscheibe ist ein Körper aus Glas.'},{q:'Womit misst du 200 ml Wasser?',o:['Glasstab','Messzylinder','Dreifuß'],a:1,why:'Der Messzylinder ist skaliert.'},{q:'Was ist beim Umgang mit unbekannten Stoffen korrekt?',o:['Probieren','Nur nach Anweisung untersuchen','Direkt riechen'],a:1,why:'Unbekannte Stoffe nicht eigenmächtig untersuchen.'},{q:'Bei 20 °C lösen sich ca. 36 g Salz in 100 g Wasser. Wie viel ungefähr in 200 g Wasser?',o:['72 g','36 g','200 g'],a:0,why:'Doppelte Wassermenge → etwa doppelte lösliche Salzmenge.'},{q:'Was bedeutet ein Bodensatz trotz gründlichem Rühren?',o:['Der Stoff ist verschwunden','Die Lösung kann gesättigt sein','Das Wasser siedet'],a:1,why:'Weiterer Feststoff kann unter diesen Bedingungen nicht gelöst bleiben.'},{q:'Wasser kann bei 20 °C ...',o:['nur sieden','schon verdunsten','gar nicht gasförmig werden'],a:1,why:'Verdunstung findet bereits unter 100 °C statt.'},{q:'Was geschieht beim Filtrieren von Sand und Wasser?',o:['Sand bleibt im Filter','Wasser wird magnetisch','Alles bleibt im Filter'],a:0,why:'Sand ist unlöslich und wird zurückgehalten.'},{q:'Die besonders heiße Zone liegt bei der blauen Brennerflamme ...',o:['im inneren Kegel','knapp über dessen Spitze','am Sockel'],a:1,why:'Im Schulmodell knapp oberhalb der Innenkegelspitze.'}];
let mockStarted=false,mockGraded=false,mockQuestions=[];
function newMockQuestions(){
  // Six subjects appear at least once; two further questions add variation.
  const groups=Object.keys(topicNames),selected=[];
  for(const subject of groups){const list=BANK.filter(q=>q[0]===subject),x=list[Math.floor(Math.random()*list.length)];selected.push({q:x[1],o:x[2],a:x[3],why:x[4]})}
  const rest=BANK.filter(q=>!selected.some(z=>z.q===q[1])).sort(()=>Math.random()-.5).slice(0,2);
  selected.push(...rest.map(x=>({q:x[1],o:x[2],a:x[3],why:x[4]})));
  return selected.sort(()=>Math.random()-.5);
}

function newMock(){mockStarted=true;mockGraded=false;mockQuestions=newMockQuestions();el('v4MockTasks').innerHTML=[...mockQuestions.map((q,i)=>`<div class="v4mocktask"><div class="v4kicker">Aufgabe ${i+1} · 1 Punkt</div><h3>${clean(q.q)}</h3><label>Meine Antwort<select data-mockchoice="${i}"><option value="">Bitte wählen</option>${q.o.map((o,j)=>`<option value="${j}">${clean(o)}</option>`).join('')}</select></label><div class="v4solution" id="v4MockSol${i}" hidden></div></div>`),...written.map((q,i)=>`<div class="v4mocktask"><div class="v4kicker">Aufgabe ${9+i} · 2 Punkte (Selbstkontrolle)</div><h3>${clean(q[0])}</h3><label>Meine Erklärung<textarea rows="3" data-mockwritten="${i}" placeholder="Schreibe in eigenen Worten ..."></textarea></label><div class="v4solution" id="v4MockSol${i+8}" hidden></div></div>`)].join('');el('v4MockDone').textContent='0/12';el('v4MockScore').textContent='–';el('v4MockGrade').hidden=false;status('v4MockFeedback','Arbeite ohne Hilfen und werte erst am Schluss aus. Für offene Fragen vergibst du selbst Punkte.');all('[data-mockchoice],[data-mockwritten]').forEach(x=>x.addEventListener('input',()=>{const answered=all('[data-mockchoice]').filter(y=>y.value!=='').length+all('[data-mockwritten]').filter(y=>y.value.trim()).length;el('v4MockDone').textContent=answered+'/12'}))}
function gradeMock(){if(!mockStarted){newMock();return}if(mockGraded)return;mockGraded=true;let objective=0;mockQuestions.forEach((q,i)=>{const v=el('v4MockTasks').querySelector(`[data-mockchoice="${i}"]`).value,ok=Number(v)===q.a&&v!=='';if(ok)objective++;const box=el('v4MockSol'+i);box.hidden=false;box.textContent=(ok?'✓ Richtig. ':'Musterlösung: '+q.o[q.a]+'. ')+q.why});written.forEach((q,i)=>{const box=el('v4MockSol'+(i+8));box.hidden=false;box.innerHTML=`<b>Musterlösung zur Selbstkontrolle:</b> ${clean(q[1])}<label style="display:block;margin-top:8px">Meine Punkte <select data-selfscore="${i}"><option value="0">0: nicht ausreichend</option><option value="1">1: teilweise richtig</option><option value="2">2: richtig erklärt</option></select></label>`});const update=()=>{let score=objective+all('[data-selfscore]').reduce((s,x)=>s+Number(x.value),0);el('v4MockScore').textContent=`${score}/16`;status('v4MockFeedback',`${objective} von 8 automatisch bewerteten Punkten. Weitere 8 Punkte werden anhand der Musterlösungen von dir selbst vergeben; dies ist keine Lehrkraftkorrektur.`,true)};all('[data-selfscore]').forEach(b=>b.addEventListener('change',update));update();el('v4MockGrade').disabled=true;mark('mock')}
el('v4MockStart').addEventListener('click',newMock);el('v4MockGrade').addEventListener('click',gradeMock);el('v4MockPrint').addEventListener('click',()=>{if(!mockStarted)newMock();printArea('v4printmock')});
// -- Material property tests. Different materials require sample assumptions.
const materials={iron:['Eisen',true,true,7.9],copper:['Kupfer',false,true,8.96],aluminium:['Aluminium',false,true,2.7],wood:['Trockenes Holz (Beispiel)',false,false,.7],plastic:['Kunststoff (Beispiel)',false,false,.95],cork:['Kork',false,false,.25],glass:['Glas',false,false,2.5]};
function propsTest(t){const [name,mag,conduct,dens]=materials[el('v4Material').value];let msg='';if(t==='mag'){msg=mag?`${name} wird vom Modellmagneten angezogen.`:`${name} wird vom Modellmagneten nicht angezogen.`}else if(t==='electric'){el('v4Bulb').classList.toggle('on',conduct);el('v4Bulb').textContent=conduct?'💡':'○';msg=conduct?`${name} leitet elektrischen Strom und schließt den vereinfachten Schaltkreis.`:`${name} ist bei üblichen Schulversuchen ein elektrischer Isolator. Im Modell bleibt die Lampe aus.`}else{const floats=dens<1;el('v4FloatObject').style.top=floats?'25px':'83px';msg=`Die angenommene Dichte von ${name.toLowerCase()} ist etwa ${String(dens).replace('.',',')} g/cm³; es ${floats?'schwimmt in Wasser':'sinkt in Wasser'} (massiver Probekörper ohne eingeschlossene Luft). Wasser hat ungefähr 1 g/cm³.`}status('v4PropertyResult',msg,true)}
el('v4MagTest').addEventListener('click',()=>propsTest('mag'));el('v4ElectricTest').addEventListener('click',()=>propsTest('electric'));el('v4FloatTest').addEventListener('click',()=>propsTest('float'));el('v4Material').addEventListener('change',()=>{el('v4Bulb').classList.remove('on');el('v4Bulb').textContent='○';el('v4FloatObject').style.top='25px';status('v4PropertyResult','Neues Prüfmaterial gewählt. Entscheide, welche Eigenschaft du untersuchen willst.')});
