function applySettings(){const s=data.settings;document.body.classList.toggle('v4dark',s.theme==='dark');document.body.classList.toggle('v4cream',s.theme==='cream');document.body.classList.toggle('v4fontlarge',s.font==='large');document.body.classList.toggle('v4fontxl',s.font==='xl');document.body.classList.toggle('v4nomotion',s.motion==='off');Object.entries({v4Theme:s.theme,v4Font:s.font,v4Motion:s.motion,v4SpeechRate:s.rate}).forEach(([id,v])=>{el(id).value=v})}
[['v4Theme','theme'],['v4Font','font'],['v4Motion','motion'],['v4SpeechRate','rate']].forEach(([id,k])=>el(id).addEventListener('change',()=>{data.settings[k]=el(id).value;applySettings();save();status('v4OptionsStatus','Einstellung auf diesem Gerät gespeichert.',true)}));el('v4ReadPage').addEventListener('click',()=>{if(!('speechSynthesis'in window)){status('v4OptionsStatus','Vorlesen wird in diesem Browser nicht unterstützt.',false);return}window.speechSynthesis.cancel();let utter=new SpeechSynthesisUtterance(el('page-v4study').innerText.slice(0,4500));utter.lang='de-DE';utter.rate=Number(data.settings.rate)||1;window.speechSynthesis.speak(utter);status('v4OptionsStatus','Vorlesen gestartet. Die Stimme wird vom Gerät bereitgestellt.')});el('v4StopRead').addEventListener('click',()=>{if('speechSynthesis'in window)window.speechSynthesis.cancel();status('v4OptionsStatus','Vorlesen gestoppt.')});el('v4ResetProgress').addEventListener('click',()=>{if(!window.confirm('Wirklich den Lernfortschritt nur für den neuen Campus zurücksetzen? Gespeicherte Forscherprotokolle bleiben erhalten.'))return;data.stats={};data.completed={};data.escape=0;data.detect={};save();renderStats();renderScene();renderEscape();status('v4OptionsStatus','Fortschritt des Forschungs-Campus zurückgesetzt. Forscherbuch bleibt erhalten.',true)});applySettings();
